root=Path('/workspace/sites/sanghapathways/dist')
nav=[('Home','/'),('Destinations','/destinations/'),('Itineraries','/itineraries/'),('Vehicle services','/vehicles/'),('Travel services','/tours/'),('Blog','/blog/'),('About us','/about/')]
phone='+91 91555 11029'
def wa(text='Hello Sanghapathways Tour India, I would like to plan a journey. Please share the options.'):
 from urllib.parse import quote
 return 'https://wa.me/919155511029?text='+quote(text)
def enquiry(label='Plan your journey',text=None,cls='button'):
 return f'<a class="{cls}" href="{wa(text) if text else wa()}" target="_blank" rel="noopener">{label} <span aria-hidden="true">↗</span></a>'
def pic(name,alt,cls=''):
 return f'<img class="{cls}" src="/images/{name}.jpg" alt="{alt}" loading="lazy" width="1200" height="800">'
def heading(kicker,title,desc):
 return f'<section class="page-heading wrap"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="intro">{desc}</p></section>'
def cta():
 return '<section class="cta wrap"><div><p class="eyebrow">A journey that feels like yours</p><h2>Let’s find your path.</h2><p>Tell us where you wish to go, who’s travelling, and how much time you have.</p></div>'+enquiry('Talk to our team')+'</section>'
def page(key,title,desc,content):
 links=''.join(f'<a href="{url}"'+(' aria-current="page"' if key==url else '')+f'>{name}</a>' for name,url in nav)
 footlinks=''.join(f'<a href="{url}">{name}</a>' for name,url in nav[1:])
 favicon="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 32 32'%3E%3Crect width='32' height='32' rx='16' fill='%23203e35'/%3E%3Ccircle cx='16' cy='16' r='10' fill='none' stroke='%23deb477' stroke-width='2'/%3E%3Cpath d='M16 6v20M6 16h20M9 9l14 14M9 23L23 9' stroke='%23deb477'/%3E%3C/svg%3E"
 out=f'''<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{title} | Sanghapathways Tour India</title><meta name="description" content="{html.escape(desc)}"><meta name="theme-color" content="#203e35"><link rel="icon" href="/images/sanghapathways-logo.jpeg"><link rel="stylesheet" href="/styles.css"></head><body><a class="skip" href="#main">Skip to content</a><div class="topbar"><div class="wrap"><span>Thoughtful journeys. Meaningful connections.</span><a href="tel:+919155511029">Bodh Gaya, India <span class="divider">|</span> {phone}</a></div></div><header><div class="wrap header-inner"><a class="brand" href="/" aria-label="Sanghapathways Tour India home"><img class="brand-logo" src="/images/sanghapathways-logo.jpeg" alt="" width="1080" height="1109"><span>Sanghapathways<small>TOUR INDIA</small></span></a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation" aria-label="Open navigation">Menu <span>☰</span></button><nav id="navigation" aria-label="Main navigation">{links}</nav>{enquiry('Get in touch',cls='button header-cta')}</div></header><main id="main">{content}{cta()}</main><footer><div class="wrap footer-grid"><div><a class="brand footer-brand" href="/"><img class="brand-logo" src="/images/sanghapathways-logo.jpeg" alt="" width="1080" height="1109"><span>Sanghapathways<small>TOUR INDIA</small></span></a><p>Rooted in Bodh Gaya.<br>Travelling with purpose.</p></div><div><h3>Explore</h3>{footlinks}</div><div><h3>Let’s connect</h3><a href="tel:+919155511029">{phone}</a><a href="tel:+918745841029">+91 87458 41029</a><a href="{wa()}" target="_blank" rel="noopener">Enquire on WhatsApp ↗</a><a href="https://www.facebook.com/p/Sanghapathways-Tour-India-100088424947925/" target="_blank" rel="noopener">Find us on Facebook ↗</a></div><div><h3>Our home</h3><p>Rajapur, Bodh Gaya<br>Bihar 824231, India</p><p class="footer-note">Tour routes, vehicles and guide arrangements are confirmed with your quotation.</p></div></div><div class="wrap footer-bottom"><span>© 2026 Sanghapathways Tour India</span><details><summary>Photography credits</summary><div id="photo-credits"><p>Photographs resized and displayed with responsive crops. <a href="https://commons.wikimedia.org/wiki/File:Mahabodhi_temple_complex,_Bodhgaya_23.jpg" target="_blank" rel="noopener">Mahabodhi Temple — Rohit Sharma</a>, <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener">CC BY-SA 4.0</a>. <a href="https://commons.wikimedia.org/wiki/File:Dhamekh_Stupa,_where_the_Buddha_gave_the_first_sermon_on_the_Four_Noble_Truths_and_the_Eightfold_Path_to_his_five_disciples,_Sarnath.jpg" target="_blank" rel="noopener">Sarnath — Ken Wieland</a>, <a href="https://creativecommons.org/licenses/by-sa/2.0/" target="_blank" rel="noopener">CC BY-SA 2.0</a>. <a href="https://commons.wikimedia.org/wiki/File:MayaDevi_Temple,_Lumbini.jpg" target="_blank" rel="noopener">Lumbini — Sashank.gaudel</a>, <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener">CC BY-SA 4.0</a>. Adapted photographs retain their respective licenses.</p></div></details><span>Walk gently. Travel thoughtfully.</span></div></footer>{floating_chat(wa)}<script src="/script.js" defer></script></body></html>'''
 path=root/('index.html' if key=='/' else key.strip('/')+'/index.html');path.parent.mkdir(parents=True,exist_ok=True);path.write_text(out)

home='''<section class="hero"><img src="/images/bodhgaya.jpg" alt="Mahabodhi Temple in Bodh Gaya, a sacred Buddhist pilgrimage destination" width="1600" height="1000" fetchpriority="high"><div class="hero-shade"></div><div class="wrap hero-content"><p class="eyebrow">BUDDHIST PILGRIMAGES &amp; THOUGHTFUL TRAVEL</p><h1>Some journeys take you<br>somewhere.<br><em>Others bring you closer.</em></h1><p>Walk in the footsteps of the Buddha. Discover sacred places,<br class="desktop"> local stories, and a little more stillness along the way.</p><div class="hero-actions"><a class="button saffron" href="/destinations/">Explore the destinations <span>↗</span></a><a class="hero-link" href="/itineraries/">Find your journey <span>→</span></a></div></div><div class="hero-caption"><span class="caption-line"></span> MAHABODHI TEMPLE · BODH GAYA, INDIA</div></section>
<div class="service-strip wrap"><div><span class="strip-number">01</span><span>Journeys with meaning<small>Sacred places. Personal itineraries.</small></span></div><div><span class="strip-number">02</span><span>People who know the place<small>Local guides and thoughtful support.</small></span></div><div><span class="strip-number">03</span><span>Your road, your pace<small>Private cars to group transport.</small></span></div></div>
<section class="wrap section"><div class="section-top"><div><p class="eyebrow">FOLLOW THE PATH</p><h2>Sacred places.<br><em>Lasting impressions.</em></h2></div><div><p>From the place of enlightenment to the birthplace of the Buddha, discover the places at the heart of the Buddhist journey.</p><a class="text-link" href="/destinations/">View all destinations <span>↗</span></a></div></div><div class="destination-grid">'''
for name,region,tag,img,anchor in [('Bodh Gaya','BIHAR, INDIA','Where the path turns inward','bodhgaya','bodh-gaya'),('Sarnath','UTTAR PRADESH, INDIA','Where the teachings began','sarnath','sarnath'),('Lumbini','NEPAL','A beginning worth returning to','lumbini','lumbini')]:
 home+=f'<a class="destination-card" href="/destinations/#{anchor}">{pic(img,name)}<div class="destination-overlay"></div><div class="destination-copy"><p class="eyebrow">{region}</p><h3>{name}</h3><p>{tag}</p></div><span class="round-arrow" aria-hidden="true">↗</span></a>'
home+='''</div></section><section class="story"><div class="wrap story-grid"><div><p class="eyebrow">YOUR COMPANION ON THE PATH</p><h2>A local beginning.<br>A more personal journey.</h2></div><div><p>Based in Bodh Gaya, Sanghapathways Tour India brings together pilgrimage planning, local guiding and road travel. Whether you’re visiting for a quiet day or exploring a wider Buddhist circuit, your journey starts with a conversation.</p><p>Space for reflection. Time for discovery. Travel planned around the people taking it.</p><a class="text-link" href="/tours/">Explore our travel services <span>↗</span></a></div></div></section><section class="wrap section"><div class="section-top"><div><p class="eyebrow">THE JOURNEY BETWEEN</p><h2>Travel comfortably.<br><em>Arrive with ease.</em></h2></div><div><p>A car for a personal escape or a Tempo Traveller for your group. Find transport that fits your plans.</p><a class="text-link" href="/vehicles/">Explore vehicle services <span>↗</span></a></div></div><div class="transport-list"><a href="/vehicles/#cars"><span>01</span><h3>Private cars</h3><p>Airport arrivals, local visits &amp; longer journeys</p><span>↗</span></a><a href="/vehicles/#groups"><span>02</span><h3>Group travel</h3><p>Tempo Travellers &amp; minibus enquiries</p><span>↗</span></a></div></section>'''
page('/','Buddhist Journeys from Bodh Gaya','Discover Buddhist pilgrimage destinations, private vehicle services and local guides with Sanghapathways Tour India, Bodh Gaya.',home)

dest=destinations(heading,enquiry,pic)
page('/destinations/','Buddhist Destinations in India & Nepal','Explore major Buddhist pilgrimage sites in India and Nepal, including Bodh Gaya, Sarnath, Lumbini, Kathmandu, Pokhara and Nagarkot.',dest)

vehicles=heading('VEHICLE SERVICES','A comfortable ride.<br><em>A considered journey.</em>','From your arrival in Gaya to the next stop on your pilgrimage, discuss private and group transport that works for your route.')
vehicles+='''<div class="wrap vehicle-banner"><span class="eyebrow">BASED IN BODH GAYA</span><h2>Local visits. Airport transfers.<br>Journeys beyond the city.</h2><p>Share your pickup point, dates, passenger count and luggage needs. We’ll help you choose a suitable vehicle and confirm a quotation.</p></div><section class="wrap section" id="cars"><div class="section-top"><div><p class="eyebrow">FIND YOUR FIT</p><h2>For you. For your group.</h2></div><p>Vehicle model, seating, luggage space and availability are confirmed before booking.</p></div><div class="vehicle-grid">'''
for n,title,desc,uses in [('01','Hatchback','A compact option for a light-travel city visit or a short transfer.','Local sightseeing · Short transfers'),('02','Sedan','A private ride for individuals, couples and smaller travel parties.','Airport pickup · Day excursions'),('03','Tempo Traveller','Keep your travel party together across multiple pilgrimage stops.','Family journeys · Pilgrimage groups'),('04','Minibus','Ask about group transport for a shared itinerary and coordinated pickups.','Larger parties · Organised group visits')]:
 vehicles+=f'<article class="vehicle-card" '+('id="groups"' if n=='03' else '')+f'><span class="vehicle-num">{n}</span><p class="eyebrow">PRIVATE TRANSPORT</p><h3>{title}</h3><p>{desc}</p><div class="vehicle-use">{uses}</div>{enquiry("Request a quotation","Hello Sanghapathways Tour India, I would like a quotation for a "+title+". My travel date, route and passenger count are: ","text-link")}</article>'
vehicles+='''</div></section><section class="story"><div class="wrap story-grid"><div><p class="eyebrow">BEFORE YOU SET OFF</p><h2>Clarity at every turn.</h2></div><div class="check-list"><p><b>01 &nbsp; Share your route</b><span>Pickup, stops, dates and your preferred travel pace.</span></p><p><b>02 &nbsp; Review your quotation</b><span>Confirm the vehicle, inclusions, driver arrangements, parking, tolls and any extra charges.</span></p><p><b>03 &nbsp; Confirm your journey</b><span>Agree the pickup details, payment terms and cancellation policy before booking.</span></p></div></div></section>'''
page('/vehicles/','Vehicle Services','Enquire about hatchbacks, sedans, Tempo Travellers and minibuses for airport transfers, local visits and pilgrimage travel from Bodh Gaya.',vehicles)

tours=travel_services(heading,enquiry,pic)
page('/tours/','Travel Services','Hotel bookings, language guides, airport assistance, ticket and train reservations, vehicles and private tour planning with Sanghapathways Tour India.',tours)

blog=heading('THE SANGHAPATHWAYS JOURNAL','A little reading.<br><em>A wider perspective.</em>','Practical notes and thoughtful inspiration for your next pilgrimage. Take a moment before you take the road.')
blog+='''<section class="wrap journal-feature">'''+pic('sarnath','Dhamek Stupa at Sarnath')+'''<div><p class="eyebrow">THE BUDDHIST PATH · TRAVEL NOTES</p><h2>One journey.<br>Four significant places.</h2><p>Bodh Gaya, Sarnath, Kushinagar and Lumbini each hold a different place in the story of the Buddha.</p><a class="text-link" href="#four-places">Read the story <span>↓</span></a></div></section><section class="wrap article-list"><article id="four-places"><div class="article-meta">01 / PILGRIMAGE</div><div><p class="eyebrow">4 MIN READ</p><h2>Understanding the four places of pilgrimage</h2><p>The Buddhist circuit is more than a sequence of landmarks. Its most significant places connect the story of the Buddha’s birth, enlightenment, first teaching and Mahaparinirvana across present-day India and Nepal.</p><details><summary>Continue reading</summary><div class="article-body"><h3>Lumbini: a beginning</h3><p>In Nepal, Lumbini is recognised as the Buddha’s birthplace. The sacred area around Maya Devi Temple offers a starting point for understanding its significance.</p><h3>Bodh Gaya: enlightenment</h3><p>The Mahabodhi Temple complex marks the place associated with the Buddha’s enlightenment. Its setting remains a living place of pilgrimage, prayer and reflection.</p><h3>Sarnath: the first teaching</h3><p>Near Varanasi, Sarnath is associated with the Buddha’s first sermon. Stupas and archaeological remains help visitors connect the landscape with the early teaching tradition.</p><h3>Kushinagar: reflection</h3><p>Traditionally associated with the Buddha’s Mahaparinirvana, Kushinagar is an important stop for pilgrims contemplating the final chapter of his life.</p><p>You do not need to see every place in one trip. Start with the time you have and allow enough room for rest and reflection between travel days.</p><p class="source-note">Further reading: <a href="https://whc.unesco.org/en/list/666/" target="_blank" rel="noopener">UNESCO: Lumbini</a>, <a href="https://whc.unesco.org/en/list/1056/" target="_blank" rel="noopener">UNESCO: Mahabodhi</a>, <a href="https://www.irctcbuddhisttrain.com/" target="_blank" rel="noopener">IRCTC Buddhist Circuit</a>.</p></div></details></div></article><article id="mindful-visit"><div class="article-meta">02 / MINDFUL TRAVEL</div><div><p class="eyebrow">3 MIN READ</p><h2>A thoughtful first visit to a Buddhist site</h2><p>A little preparation helps you settle into the pace of a sacred place. Arrive with curiosity, dress considerately, and allow time to observe.</p><details><summary>Continue reading</summary><div class="article-body"><h3>Let the place guide your pace</h3><p>Pause before entering an active prayer area. Keep your voice low and give worshippers space. Each monastery or temple has its own customs, so follow posted guidance and ask when unsure.</p><h3>Ask before you photograph</h3><p>Photography may be restricted in particular areas. Check local rules, and ask permission before photographing people, ceremonies or private spaces.</p><h3>Prepare for the practical details</h3><p>Wear clothing that covers shoulders and knees, carry water for the journey, and choose footwear that is easy to remove where required. Check current opening arrangements and entry restrictions for the sites on your route.</p><h3>Leave room for stillness</h3><p>You do not need to practise Buddhism to visit respectfully. A few quiet minutes can be as memorable as a long sightseeing list. Keep the surroundings clean and follow the instructions of site staff.</p></div></details></div></article><article id="planning"><div class="article-meta">03 / ON THE ROAD</div><div><p class="eyebrow">3 MIN READ</p><h2>Planning your pilgrimage around your people</h2><p>The best route is one your whole group can enjoy. Start with comfort, travel time and the experience you want to share.</p><details><summary>Continue reading</summary><div class="article-body"><h3>Begin with your must-visit places</h3><p>Choose the sites that matter most to your group before deciding how many stops to include. A shorter itinerary with unhurried visits can be more rewarding than covering every destination.</p><h3>Make comfort part of the plan</h3><p>Tell your organiser about luggage, walking preferences and any mobility needs. Confirm seating, road travel time and rest stops when choosing a vehicle.</p><h3>Agree what is included</h3><p>Ask for a written quotation that clearly sets out transport, guide services, accommodation where requested and additional charges. Confirm payment and cancellation terms before booking.</p><h3>Plan international stops early</h3><p>If Lumbini is part of the journey, discuss the border crossing in advance. Check official entry requirements for your nationality and confirm that the transport arrangements cover the proposed route.</p></div></details></div></article></section>'''
page('/blog/','Journal & Travel Notes','Read practical Buddhist pilgrimage travel notes, sacred destination guides and planning ideas from Sanghapathways.',blog)

# The supplied itineraries are the source of truth for each daily schedule.
import json
itinerary_data=json.loads((Path(__file__).parent/'itineraries.json').read_text())
esc=html.escape
itineraries=heading('OUR PILGRIMAGE ITINERARIES','Choose your path.<br><em>Make it meaningful.</em>','Five journeys through the sacred places of India and Nepal. From a quiet stay in Bodh Gaya to a wider pilgrimage, find the route that speaks to you.')
itineraries+='<nav class="wrap duration-nav" aria-label="Choose an itinerary">'
for t in itinerary_data:
 itineraries+=f'<a href="#{t["code"].lower()}"><strong>{t["duration"]} days</strong><span>{t["nights"]} nights · {esc(t["region"])}</span></a>'
itineraries+='</nav><div class="wrap itinerary-intro"><p>Explore the daily programme, save a copy, and contact us to discuss your dates and group.</p><span>5 itineraries · 3–10 days</span></div><div class="wrap itinerary-collection">'
for t in itinerary_data:
 code=t['code'].lower()
 itineraries+=f'<article class="itinerary" id="{code}"><div class="itinerary-cover">{pic(t["image"],t["start"] if t["image"]=="bodhgaya" else "Lumbini" if t["image"]=="lumbini" else "Sarnath")}<span class="duration-badge">{t["nights"]} nights <i>/</i> {t["duration"]} days</span></div><div class="itinerary-overview"><p class="eyebrow">BUDDHIST SACRED PILGRIMAGE · {esc(t["region"].upper())}</p><h2>{esc(t["title"])}</h2><p>{esc(t["intro"])}</p><dl class="journey-facts"><div><dt>START</dt><dd>{esc(t["start"])}</dd></div><div><dt>FINISH</dt><dd>{esc(t["end"])}</dd></div><div><dt>DURATION</dt><dd>{t["nights"]} nights / {t["duration"]} days</dd></div></dl><div class="route-trail" aria-label="Route">'
 for stop in t['route']:itineraries+=f'<span>{esc(stop)}</span>'
 itineraries+=f'</div><div class="itinerary-actions">{enquiry("Enquire about this tour", "Hello Sanghapathways Tour India, I am interested in the "+str(t["nights"])+" nights / "+str(t["duration"])+" days itinerary. Please share a quotation for my travel dates and group.")}<a class="download-link" href="/itineraries/downloads/Sanghapathways_Tour_India_{t["code"]}.pdf" download>Download itinerary <span>↓</span><small>Branded PDF</small></a></div></div><details class="itinerary-programme"><summary><span><span class="eyebrow">YOUR JOURNEY, DAY BY DAY</span>Explore the {t["duration"]}-day programme</span><span class="expand-indicator" aria-hidden="true"></span></summary><div class="day-timeline">'
 for day in t['days']:
  itineraries+=f'<section class="itinerary-day"><div class="day-marker"><span>DAY</span><strong>{day["number"]:02d}</strong></div><div class="day-content"><h3>{esc(day["title"])}</h3><ul>'
  for activity in day['activities']:itineraries+=f'<li>{esc(activity)}</li>'
  itineraries+=f'</ul><p class="day-meals"><b>Meals</b> {esc(day["meals"])}</p></div></section>'
 itineraries+='</div><p class="itinerary-footnote">Confirm travel dates, accommodation, meal arrangements, inclusions and pricing with our team before booking.</p></details></article>'
itineraries+='</div>'
page('/itineraries/','Buddhist Tour Itineraries','Explore 2N/3D, 4N/5D, 6N/7D, 7N/8D and 9N/10D Buddhist pilgrimage itineraries with day-by-day schedules and downloads from Sanghapathways Tour India.',itineraries)

about=heading('ABOUT SANGHAPATHWAYS TOUR INDIA','Rooted in Bodh Gaya.<br><em>Connected by the journey.</em>','We bring pilgrimage planning, local guiding and road travel together, helping you experience sacred places with time for discovery and reflection.')
about+='''<section class="wrap about-intro"><div class="about-logo-panel"><img src="/images/sanghapathways-logo.jpeg" alt="Sanghapathways Tour India — Buddha seated on a lotus within a Dharma wheel" width="1080" height="1109"><p class="eyebrow">SANGHAPATHWAYS TOUR INDIA</p></div><div><p class="eyebrow">OUR STORY STARTS HERE</p><h2>A place of meaning.<br>A personal welcome.</h2><p>Bodh Gaya is our home and the starting point for many of the journeys we plan. From time at the Mahabodhi Temple to visits across the wider Buddhist circuit, Sanghapathways Tour India helps bring the practical details of your pilgrimage together.</p><p>Our itineraries range from a three-day stay in Bodh Gaya to longer journeys through India and Nepal. Along the way, we coordinate travel and guide enquiries around your route, your companions and the experience you want to have.</p><p>Whether you are travelling individually, with family or as a pilgrimage group, we start by listening.</p></div></section><section class="story about-values"><div class="wrap"><p class="eyebrow">HOW WE APPROACH YOUR JOURNEY</p><h2>Care in the details.<br><em>Meaning in the moments.</em></h2><div class="info-grid"><article><span class="eyebrow">01 / THOUGHTFUL PLANNING</span><h3>People before a programme.</h3><p>We discuss your time, priorities and travel needs so that the route works for the people taking it.</p></article><article><span class="eyebrow">02 / RESPECT FOR PLACE</span><h3>Travel with consideration.</h3><p>Sacred sites are living places of worship. Our approach makes room for local customs, quiet reflection and a respectful visit.</p></article><article><span class="eyebrow">03 / PERSONAL CONNECTION</span><h3>A conversation, from the start.</h3><p>Speak to us directly about your itinerary, transport and guiding needs, and agree the arrangements before you travel.</p></article></div></div></section><section class="wrap section"><div class="section-top"><div><p class="eyebrow">WHAT WE CAN HELP YOU WITH</p><h2>Your journey,<br><em>brought together.</em></h2></div><p>Pilgrimage itineraries, road transport and local guide services, all starting with a conversation about your plans.</p></div><div class="about-service-grid"><a href="/itineraries/"><span class="eyebrow">01 / PLAN THE PATH</span><h3>Pilgrimage journeys</h3><p>Explore five itineraries, from Bodh Gaya stays to India and Nepal circuits.</p><span class="text-link">Explore itineraries ↗</span></a><a href="/vehicles/"><span class="eyebrow">02 / TAKE THE ROAD</span><h3>Vehicle services</h3><p>Enquire about private cars, Tempo Travellers and minibuses for your group.</p><span class="text-link">View vehicle services ↗</span></a><a href="/tours/"><span class="eyebrow">03 / LOOK A LITTLE DEEPER</span><h3>Local guides</h3><p>Ask about guidance that brings the places and their stories into focus.</p><span class="text-link">Explore guiding ↗</span></a></div></section><section class="wrap about-contact"><div><p class="eyebrow">MEET US AT THE BEGINNING</p><h2>Let’s talk about<br>your next journey.</h2></div><div><p><strong>Sanghapathways Tour India</strong><br>Rajapur, Bodh Gaya<br>Bihar 824231, India</p><a href="tel:+919155511029">+91 91555 11029</a><a href="tel:+918745841029">+91 87458 41029</a></div></section>'''
page('/about/','About Us','Meet Sanghapathways Tour India, based in Bodh Gaya, offering Buddhist pilgrimage itineraries, local guide services and private and group transport.',about)
